<script setup lang="ts">
import {computed,onMounted,onUnmounted,ref} from 'vue'
import {localFetch,readJson} from './http'
import Icon from './Icon.vue'

type Result={status?:string;message?:string;absolute_error?:number;open_error?:number;close_absolute_error?:number;close_error?:number;direction_correct?:boolean;inside_outer?:boolean;actual?:{open:number;high:number;low:number;close:number};touches?:Record<string,boolean>}
type OpeningMarket={symbol:string;name:string;gap_pct?:number;from_open_pct?:number;status?:string}
type Forecast={report_id:string;basis_date:string;created_at:string;target_date:string|null;eligible:boolean;timely:boolean;primary:boolean;prediction:{contract:string|null;resistance1:number|null;resistance2:number|null;open:number|null;close?:number|null;raw_open?:number|null;raw_close?:number|null;support1:number|null;support2:number|null;reason:string;calibration?:{applied:boolean;open_adjustment:number;close_adjustment:number;open_model_samples:number;close_model_samples:number};opening_markets?:{rows?:OpeningMarket[]}};result:Result}
type State={forecasts:Forecast[];model?:{futures?:{open?:{status:string;samples:number;minimum:number};close?:{status:string;samples:number;minimum:number}}}|null;summary:{forecasts:number;mae:number|null;bias:number|null;close_mae:number|null;close_bias:number|null;direction_rate:number|null;range_rate:number|null};job:{status:string;message:string;finished_at?:string;errors?:string[]};method:string}

const emit=defineEmits<{research:[]}>()
const state=ref<State|null>(null),error=ref(''),busy=ref(false),day=ref(''),scope=ref('all'),status=ref('all')
let timer:ReturnType<typeof setTimeout>|undefined,alive=true,epoch=0
const labels:Record<string,string>={pending:'等待行情',scored:'已核對',missing:'缺少預測'}
const f=(v:number|null|undefined,d=2)=>v==null?'—':v.toLocaleString('zh-TW',{maximumFractionDigits:d})
const signed=(v:number|null|undefined,d=2)=>v==null?'—':(v>0?'+':'')+f(v,d)
const stamp=(v:string)=>v.replace('T',' ').slice(0,16)
const dates=computed(()=>[...new Set((state.value?.forecasts||[]).map(r=>r.basis_date))].sort().reverse())
const forecasts=computed(()=>(state.value?.forecasts||[]).filter(r=>(!day.value||r.basis_date===day.value)&&(scope.value==='all'||scope.value==='forward'&&r.eligible||scope.value==='history'&&!r.timely||scope.value==='revisions'&&!r.primary)&&(status.value==='all'||(r.result.status||'pending')===status.value)))

async function api(url:string,body?:unknown){const response=await localFetch(url,body===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const data=await readJson(response);if(!response.ok)throw new Error(data.error||'無法讀取資料');return data}
async function load(){const token=++epoch;clearTimeout(timer);try{const data=await api('/api/futures');if(!alive||token!==epoch)return;state.value=data;busy.value=data.job.status==='running';if(busy.value)timer=setTimeout(load,2000)}catch(reason){if(alive)error.value=(reason as Error).message}}
async function refresh(){busy.value=true;error.value='';try{await api('/api/futures/refresh',{});await load()}catch(reason){error.value=(reason as Error).message;busy.value=false}}
onMounted(load);onUnmounted(()=>{alive=false;epoch++;clearTimeout(timer)})
</script>

<template>
<section class="forecast-page">
 <header class="page-header"><div><div class="eyebrow">RESEARCH · FUTURES FORECAST JOURNAL</div><h1>台指預測記錄</h1><p>下一交易日日盤開盤與收盤 · 永久保存首版預測，再由滾動模型校正並核對。</p></div><button class="primary" :disabled="busy" @click="refresh"><Icon name="refresh" :class="{spinning:busy}"/>{{busy?'更新行情中':'更新台指行情'}}</button></header>
 <div v-if="error" class="error-banner" role="alert">{{error}}</div>
 <div class="journal-status"><span>{{state?.job.message||'讀取紀錄中…'}}</span><small v-if="state?.job.finished_at">更新 {{stamp(state.job.finished_at)}}</small><button @click="emit('research')">前往收盤研究 →</button></div>
 <div v-if="state?.model?.futures" class="model-overview"><span><b>台指開盤／收盤模型</b> {{state.model.futures.open?.samples||0}}/{{state.model.futures.open?.minimum||12}} · {{state.model.futures.close?.samples||0}}/{{state.model.futures.close?.minimum||12}} 筆</span></div>
 <div v-if="state?.summary" class="journal-cards"><article class="panel"><span>開盤平均絕對誤差</span><strong>{{f(state.summary.mae)}}<small>點</small></strong><p>{{state.summary.forecasts}} 筆已核對首版預測</p></article><article class="panel"><span>收盤平均絕對誤差</span><strong>{{f(state.summary.close_mae)}}<small>點</small></strong><p>平均偏差 {{signed(state.summary.close_bias)}} 點</p></article><article class="panel"><span>多空方向命中</span><strong>{{f(state.summary.direction_rate,1)}}<small>%</small></strong><p>比較預測與實際的開盤至收盤方向</p></article><article class="panel"><span>全日落在外側區間</span><strong>{{f(state.summary.range_rate,1)}}<small>%</small></strong><p>當日低 ≥ 支撐2，當日高 ≤ 壓力2</p></article></div>
 <p class="journal-note">台指統計只採每研究日第一份完整報告，須在目標日08:45前完成。事後報告與重產版本另列，未取得實際行情者不計誤差；點位觸及不等於交易獲利。</p>
 <div class="journal-filters"><label>研究日<select v-model="day"><option value="">所有日期</option><option v-for="date in dates" :key="date">{{date}}</option></select></label><label>紀錄<select v-model="scope"><option value="all">全部版本</option><option value="forward">盤前首版</option><option value="history">事後／日期待確認</option><option value="revisions">重產版本</option></select></label><label>狀態<select v-model="status"><option value="all">全部狀態</option><option value="scored">已核對</option><option value="pending">等待行情</option><option value="missing">缺少預測</option></select></label></div>
 <section class="forecast-list"><article v-for="row in forecasts" :key="row.report_id" class="panel forecast-card"><header><div><small>研究日 {{row.basis_date}} · {{stamp(row.created_at)}}</small><h2>{{row.target_date||'日期待確認'}} <span>08:45–13:45 · TX {{row.prediction.contract||'契約待補'}}</span></h2></div><span class="journal-badge">{{row.eligible?'盤前首版':!row.primary?'重產版本':'事後／日期待確認'}} · {{labels[row.result.status||'pending']}}</span></header><div class="forecast-points"><div><span>壓力 2</span><strong>{{f(row.prediction.resistance2)}}</strong></div><div><span>壓力 1</span><strong>{{f(row.prediction.resistance1)}}</strong></div><div class="opening"><span>預測開盤</span><strong>{{f(row.prediction.open)}}</strong></div><div class="closing"><span>預測收盤</span><strong>{{f(row.prediction.close)}}</strong></div><div><span>支撐 1</span><strong>{{f(row.prediction.support1)}}</strong></div><div><span>支撐 2</span><strong>{{f(row.prediction.support2)}}</strong></div></div><div v-if="row.prediction.calibration" class="model-status"><b>{{row.prediction.calibration.applied?'已套用滾動校正':'模型暖機中'}}</b><span>開盤 {{signed(row.prediction.calibration.open_adjustment)}} 點 · 收盤 {{signed(row.prediction.calibration.close_adjustment)}} 點</span><span>樣本 {{row.prediction.calibration.open_model_samples}}／{{row.prediction.calibration.close_model_samples}}</span></div><div v-if="row.prediction.opening_markets?.rows?.length" class="opening-context"><span v-for="market in row.prediction.opening_markets.rows" :key="market.symbol"><b>{{market.name}}</b> {{market.gap_pct==null?(market.status||'待核實'):'跳空 '+signed(market.gap_pct)+'%／開盤後 '+signed(market.from_open_pct)+'%'}}</span></div><div v-if="row.result.actual" class="forecast-outcome"><span>實際開盤 <b>{{f(row.result.actual.open)}}</b></span><span>實際收盤 <b>{{f(row.result.actual.close)}}</b></span><span>最高 {{f(row.result.actual.high)}}</span><span>最低 {{f(row.result.actual.low)}}</span><span>開盤偏差 <b>{{signed(row.result.open_error)}} 點</b></span><span>收盤偏差 <b>{{signed(row.result.close_error)}} 點</b></span><span>{{row.result.direction_correct===true?'多空方向命中':row.result.direction_correct===false?'多空方向未命中':'方向待核對'}}</span><span>{{row.result.inside_outer?'全日在外側區間內':'已突破外側區間'}}</span><span v-for="(label,key) in {resistance1:'壓力1',resistance2:'壓力2',support1:'支撐1',support2:'支撐2'}" :key="key">{{label}} {{row.result.touches?.[key]?'觸及':'未觸及'}}</span></div><p v-else class="journal-note">{{row.result.message||'等待目標日日盤行情。'}}</p><details><summary>預測依據與檢討</summary><p>{{row.prediction.reason}}</p><small>原始開盤 {{f(row.prediction.raw_open)}}／收盤 {{f(row.prediction.raw_close)}} 永久保留；模型只使用當時以前已揭曉的首版結果。</small></details></article><div v-if="!forecasts.length" class="panel journal-empty">{{state?.forecasts.length?'目前篩選沒有符合紀錄。':'新研究報告會記錄台指開盤、收盤與四個區間點位，隔日更新行情後核對。'}}</div></section>
 <details v-if="state?.job.errors?.length" class="journal-errors"><summary>{{state.job.errors.length}} 項缺口</summary><p v-for="message in state.job.errors" :key="message">{{message}}</p></details>
 <p class="journal-method">{{state?.method}}</p>
</section>
</template>

<style scoped>
.journal-status{display:flex;align-items:center;flex-wrap:wrap;gap:14px;background:#edf2e9;padding:14px 18px;border-radius:8px;font-size:.78rem;margin-bottom:12px}.journal-status>span{flex:1}.journal-status small{color:#85927b}.journal-status button{color:#557446;text-decoration:underline}.model-overview{display:flex;gap:12px;flex-wrap:wrap;margin-bottom:22px}.model-overview span{padding:8px 12px;background:#f5f7f1;border:1px solid #e3eadc;border-radius:6px;font-size:.68rem;color:#829078}.model-overview b{color:#5c754f}.journal-cards{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:20px}.journal-cards article{padding:24px}.journal-cards article>span{font-size:.82rem;color:#7f8e72}.journal-cards strong{display:block;font-size:2rem;font-weight:500;margin-top:18px}.journal-cards strong small{font-size:.85rem;margin-left:7px;color:#91a084}.journal-cards p{font-size:.72rem;color:#8a967e}.journal-note,.journal-method{font-size:.75rem;color:#859477;line-height:1.9;margin:18px 0 25px}.journal-method{border-top:1px solid #e3eadc;padding-top:20px}.journal-filters{display:flex;gap:15px;align-items:end;flex-wrap:wrap;margin:24px 0 16px}.journal-filters label{font-size:.74rem;display:flex;flex-direction:column;gap:7px}.journal-filters select{border:1px solid #d8e1d0;background:white;border-radius:6px;padding:10px;color:#4d6343;font-size:.8rem}.journal-badge{display:inline-block;padding:5px 8px;background:#eff3e9;color:#72885d;border-radius:5px;font-size:.7rem}.journal-empty{text-align:center;padding:60px 25px!important;line-height:1.9;color:#8c9a80}.forecast-list{display:grid;gap:20px}.forecast-card{padding:26px}.forecast-card header{display:flex;justify-content:space-between;align-items:start;gap:15px}.forecast-card header small{color:#91a084;font-size:.72rem}.forecast-card h2{font-size:1.2rem;font-weight:500;margin:10px 0 25px}.forecast-card h2 span{font-size:.8rem;color:#87997c}.forecast-points{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:10px}.forecast-points>div{padding:18px 10px;background:#f6f8f2;border-radius:7px;text-align:center}.forecast-points span{font-size:.72rem;color:#839674}.forecast-points strong{display:block;margin-top:13px;font-size:1.3rem;font-weight:500}.forecast-points .opening{background:#e7efdf;border:1px solid #c5d4b7}.forecast-points .closing{background:#eef1e7;border:1px solid #d1d9c7}.model-status{display:flex;gap:14px;align-items:center;flex-wrap:wrap;margin-top:13px;padding:10px 13px;background:#f5f7f1;border-radius:6px;font-size:.7rem;color:#809074}.model-status b{color:#5e7752}.opening-context,.forecast-outcome{display:flex;gap:15px;flex-wrap:wrap;font-size:.79rem;border-bottom:1px solid #e6eddf;padding:20px 0;margin-bottom:20px}.opening-context span{background:#f2f6ed;padding:8px 10px;border-radius:5px}.forecast-card details{font-size:.78rem;color:#81936f;margin-top:20px;line-height:1.9}.forecast-card details p{white-space:pre-wrap}.journal-errors{margin-top:20px;font-size:.77rem;color:#9a8151}@media(max-width:1100px){.journal-cards{grid-template-columns:repeat(2,1fr)}}@media(max-width:850px){.journal-cards{grid-template-columns:1fr}.forecast-points{grid-template-columns:repeat(6,minmax(80px,1fr));overflow:auto}.forecast-card header{flex-direction:column}.forecast-points strong{font-size:1rem}.journal-filters{align-items:stretch}.journal-cards strong{margin-top:8px}}
</style>
